#!/usr/bin/env python3
"""Rebuild counts from the reviewed, anonymized coding. Does not classify text."""
import json
from pathlib import Path
from collections import Counter
from datetime import datetime
from zoneinfo import ZoneInfo
P=Path(__file__).resolve().parent
read=lambda name: [json.loads(line) for line in (P/name).read_text().splitlines()]
labels={'food':'Вкус, приготовление и качество еды','temperature':'Холодная или остывшая еда','waiting':'Долгое ожидание и нарушение времени','completeness':'Недокомплект и ошибки в заказе','value':'Цена, размер порции и количество начинки','presentation':'Внешний вид и упаковка','communication':'Общение и решение проблем','ordering':'Оформление, оплата и доступность заказа','menu_options':'Не хватает нужных позиций или дополнений'}
s=read('starter-coded.jsonl');p=read('public-coded.jsonl');i=read('internal-coded.jsonl');eda=read('eda-conditional-coded.jsonl');m=read('starter-period-metadata.jsonl')
assert len(s)==1310 and len(m)==3580
assert len({r['feedback_id'] for r in s})==len(s)
assert {r['feedback_id'] for r in s}=={r['feedback_id'] for r in m if r['has_text']}
mm={r['feedback_id']:r for r in m}
for r in s:
 assert r['date']==datetime.fromisoformat(mm[r['feedback_id']]['created_at']).astimezone(ZoneInfo('Europe/Moscow')).date().isoformat()
 assert r['rating']==mm[r['feedback_id']]['rating']
 assert r['source_comment_sha256']==mm[r['feedback_id']]['comment_sha256']
netp=[r for r in p if r['included_in_combined']]
allrows=s+netp+i
for r in allrows:
 assert r['date'][:4] in ('2025','2026')
 assert len(r['codes'])==len(set(r['codes'])) and set(r['codes'])<=set(labels)
 assert bool(r['codes'])==(r['status']=='specific_issue')
counts=lambda rows: Counter(c for r in rows for c in r['codes'])
sc,pc,ic,total=map(counts,(s,netp,i,allrows))
ranking=[{'code':c,'topic':labels[c],'starter':sc[c],'maps_net':pc[c],'revvy_internal':ic[c],'total':total[c]} for c in sorted(labels,key=lambda c:(-total[c],c))]
result={'as_of':'2026-10-13','period':'2025-01-01 through2026-10-13','unit':'Source observations after2 exact crossposts removed; NOT unique people/orders. One topic at most once per observation.','coverage':{'starter_ratings':len(m),'starter_texts':len(s),'starter_empty':len(m)-len(s),'starter_text_statuses':dict(Counter(r['status'] for r in s)),'starter_five_star_specific_issues':sum(r['rating']==5 and bool(r['codes']) for r in s),'public_records':len(p),'public_texts':sum(r['text_present'] for r in p),'public_source_counts':dict(Counter(r['source'] for r in p)),'public_records_after_exact_crossposts':len(netp),'internal_specific_episodes':len(i),'eda_year_unconfirmed_excluded':len(eda),'combined_observations_with_specific_issues':sum(bool(r['codes']) for r in allrows)},'ranking':ranking,'starter_by_year':{str(y):{'ratings':sum(r['created_at'][:4]==str(y) for r in m),'texts':sum(r['year']==y for r in s),'specific_issue_texts':sum(r['year']==y and bool(r['codes']) for r in s),'topics':dict(counts([r for r in s if r['year']==y]))} for y in (2025,2026)},'conditional_eda_addition':dict(counts(eda)),'limits':['Sources can still describe same event; exact-text check is not complete customer/order deduplication.','Food includes8 unverified reports of illness; no causal/medical conclusion.','Prompted WhatsApp survey excluded; media not analyzed; current snapshot only.']}
(P/'complaint-ranking.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
header='''# Рейтинг жалоб: только 2025–2026, со Starter\n\nСрез **13.10.2026**. Период определяется датой отзыва или сообщения: с 01.01.2025; 2023–2024 исключены. Прочитаны все **1 310 текстов Starter** из **3 580 записей** за период; остальные **2 270** — оценки без объяснения. Пять звёзд не исключают конкретной жалобы.\n\nЕдиница — отзыв/эпизод в источнике, содержащий указанную тему. В одном отзыве может быть несколько тем, каждая считается один раз. Это не число уникальных клиентов или проблемных заказов и не процент брака.\n\n| Тема | Starter | Карты* | Revvy, внутренние обращения | Всего |\n|---|---:|---:|---:|---:|\n'''
rows=''.join(f"| {r['topic']} | {r['starter']} | {r['maps_net']} | {r['revvy_internal']} | **{r['total']}** |\n" for r in ranking)
footer=f'''
\n*Яндекс и Google Карты из публичного экспорта Revvy. 149 записей, 141 текст. Перед суммированием исключены две повторные публикации: public:R121 совпадает со Starter:8009 (одна негативная публикация того же дня); public:R004 совпадает с public:R003 (положительный текст в двух площадках). Источник каждого наблюдения сохранён. Полное сопоставление по заказам/людям не выполнено: другие межканальные повторы возможны.\n\nВ Starter **{sum(bool(r['codes']) for r in s)}** текстов с конкретной проблемой, в том числе **{result['coverage']['starter_five_star_specific_issues']}** с оценкой 5. С учётом остальных источников и двух исключённых повторов — **{result['coverage']['combined_observations_with_specific_issues']} наблюдения с конкретикой**. Сумма строк таблицы больше: один отзыв может содержать несколько претензий. Эти числа не измеряют долю неудовлетворённых клиентов.\n\n## Что изменилось и что это означает\n\n- Качество еды остаётся наиболее частой темой. Это объединяет вкус, рис/текстуру, приготовление, состояние ингредиентов и посторонние предметы; это не одна установленная причина.\n- Starter выводит температуру на второе место, ожидание — на третье. Холодное блюдо и задержка часто описаны вместе; их нельзя складывать в независимые случаи.\n- Следующий заметный блок — комплектация: забытые дополнения, перепутанные позиции, невыполненные указания. Невыданный ожидаемый подарок фиксируется как сообщение клиента; право на него отдельно не подтверждено.\n- Цена и наполнение объединены в отдельную тему. Редкость ценовых жалоб в этом корпусе не доказывает, что цена приемлема для ушедших или некупивших. Новые опросы должны сравнивать причины выбора и изменения, способные увеличить заказы.\n\n## Яндекс Еда: отдельно из-за точности даты\n\nТри отзыва Еды содержат только день и месяц. Предполагаемый год — 2026, но он не отображён в сохранённом источнике. Для строгого ограничения 2025–2026 **они не включены** в таблицу. Один из них содержит претензии к вкусу мидий и температуре; условное добавление даёт **+1 к качеству и +1 к температуре**, не меняя порядок. Файл: [eda-conditional-coded.jsonl](eda-conditional-coded.jsonl).\n\n## Полнота и ограничения\n\n- Starter: полный сохранённый массив за период, все1310 текстов смыслово прочитаны. 67 записей с медиа: изображения не открывались. Отсутствие тематических тегов в API не означает отсутствие жалоб.\n- Публичный экспорт: все141 текста за2025–2026 прочитаны заново по общему кодбуку, включая высокие оценки. Интерфейс Карт не добавляется второй раз поверх того же экспорта Revvy.\n- Внутренний Revvy:12 конкретных эпизодов из16 выбранных отрицательных историй/120 сообщений, всё в2026. Это не все обращения сервиса.\n- **8 сообщений Starter о недомогании после еды** сохранены в food с подтипом reported_symptoms_unverified. Это свидетельства о жалобах; диагноз, причина и связь с продуктом не проверены.\n- Рейтинг за весь2025 и неполный2026 не является сравнением динамики. Отдельные годовые счётчики доступны в JSON; без сопоставимых периодов/числа заказов не трактовать изменение как улучшение или ухудшение.\n- Ответы старого WhatsApp опроса не смешаны со спонтанными жалобами: у них подсказанные варианты и другой способ сбора.\n\n## Проверяемость\n\n[Кодбук](codebook.md), [Starter:1310 строк кодировки](starter-coded.jsonl), [публичные отзывы](public-coded.jsonl), [внутренние эпизоды](internal-coded.jsonl), [решения после проверки](coding-decisions.json), [manifest](manifest.json). Исходные тексты находятся в постоянном приватном архиве, указанном в основном README; имена и контакты в Git не добавлены.\n\nТри части Starter проверены независимыми повторными выборками: все69 записей первоначальной средней/низкой уверенности и90 записей высокой, всего159; публично повторно проверены35 текстов. Дополнительно разрешены пограничные случаи и сообщения о недомогании. Это контроль качества разметки, не второе полное чтение всеми проверяющими.\n\nПересчитать без доступа к личным данным:\n\n```bash\npython3 business-docs/marketing/customer-feedback-research/snapshots/2026-10-13/ranking-2025-2026/rebuild-ranking.py\n```\n\nСкрипт только суммирует уже проверенную разметку и проверяет ID, даты, оценки, хеши, коды. Он не подменяет смысловое чтение классификацией по словам. Старый рейтинг в previous-corpus сохранён как история; он охватывает другой период и не включает Starter.\n'''
(P/'complaint-ranking.md').write_text(header+rows+footer)
print(json.dumps({'coverage':result['coverage'],'ranking':ranking},ensure_ascii=False,indent=2))
